// Formato do ID e limite de consultas, ANTES de qualquer leitura da planilha.
const LIMITE = 10;      // consultas por visitante
const JANELA = 60000;   // ms

const req = $input.first().json;
const bruto = String((req.query || {}).id ?? '').trim();
if (!bruto) return [{ json: { estado: 'vazio', id: '' } }];

// IP real do visitante: último endereço do X-Forwarded-For (o que o proxy
// da hospedagem acrescentou); o visitante não controla essa posição.
const headers = req.headers || {};
const encaminhado = String(headers['x-forwarded-for'] || '').split(',').map(s => s.trim()).filter(Boolean);
const ip = encaminhado.pop() || String(headers['x-real-ip'] || 'desconhecido');

// ponytail: contador nos dados estáticos do fluxo (só em execução de produção,
// sem trava entre execuções simultâneas). Teto: limite aproximado; se precisar
// de exatidão, mover a validação para a versão Python.
const dados = $getWorkflowStaticData('global');
const agora = Date.now();
const hits = dados.hits || {};
for (const k of Object.keys(hits)) {
  hits[k] = hits[k].filter(t => agora - t < JANELA);
  if (!hits[k].length) delete hits[k];
}
const meus = hits[ip] || [];
if (meus.length >= LIMITE) {
  dados.hits = hits;
  return [{ json: { estado: 'limite', id: '' } }];
}
meus.push(agora);
hits[ip] = meus;
dados.hits = hits;

// ID fora do formato é rejeitado aqui, sem consultar a planilha.
const valido = /^[A-Za-z0-9]{12}$/.test(bruto);
return [{ json: { estado: valido ? 'consultar' : 'nao_encontrado', id: valido ? bruto : '' } }];

// ===== Configuração (preencha no seu n8n; nunca no repositório) =====
const EMISSOR = 'Escola Exemplo de Idiomas';
const URL_VALIDACAO = 'https://exemplo.com/webhook/validar';  // endereço público deste fluxo
const LINKEDIN_ORGANIZATION_ID = '';  // opcional: ID numérico da página no LinkedIn
// ====================================================================

const TIPOS = {
  certificado_curso: 'Certificado de conclusão de curso',
  certificado_semestre: 'Certificado de conclusão de semestre',
  certificado_trimestre: 'Certificado de conclusão de trimestre',
  declaracao_matricula: 'Declaração de matrícula',
  declaracao_termino_semestre: 'Declaração de término de semestre',
};
const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho',
  'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];

const esc = v => String(v ?? '').replace(/[&<>"']/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const txt = v => String(v ?? '').trim();

function data(valor) {  // 'AAAA-MM-DD' ou 'DD/MM/AAAA' -> {dia, mes, ano}, ou null
  let m = txt(valor).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return { ano: +m[1], mes: +m[2], dia: +m[3] };
  m = txt(valor).match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (m) return { ano: +m[3], mes: +m[2], dia: +m[1] };
  return null;
}

const { estado, id } = $('Preparar').first().json;
const entrada = $input.all().map(i => i.json);
let resultado = estado;
let doc = null;
let linkedin = '';

if (entrada.some(r => r.error)) {
  resultado = 'indisponivel';  // falha ao ler a planilha: detalhe só no n8n
} else if (estado === 'consultar') {
  // Nenhuma linha, ou o mesmo ID em mais de uma linha (ambíguo): não encontrado.
  const linhas = entrada.filter(r => txt(r.id) === id);
  if (linhas.length !== 1) {
    resultado = 'nao_encontrado';
  } else {
    const r = linhas[0];
    const tipo = txt(r.tipo_documento);
    const d = data(r.data_emissao);
    if (txt(r.status).toLowerCase() !== 'ativo' || !TIPOS[tipo]) {
      resultado = 'invalido';
    } else {
      resultado = 'valido';
      // Só os campos públicos. Nunca CPF, RG, endereço ou outro dado do aluno.
      doc = {
        tipo: TIPOS[tipo],
        nome: txt(r.nome),
        curso: txt(r.curso),
        carga_horaria: txt(r.carga_horaria),
        data_emissao: d ? `${d.dia} de ${MESES[d.mes - 1]} de ${d.ano}` : '',
      };
      if (tipo.startsWith('certificado_') && d && URL_VALIDACAO) {
        const params = {
          startTask: 'CERTIFICATION_NAME',
          name: `${TIPOS[tipo]} — ${txt(r.curso)}`,
          ...(LINKEDIN_ORGANIZATION_ID ? { organizationId: LINKEDIN_ORGANIZATION_ID } : { organizationName: EMISSOR }),
          issueYear: d.ano,
          issueMonth: d.mes,
          certUrl: `${URL_VALIDACAO}?id=${id}`,
          certId: id,
        };
        linkedin = 'https://www.linkedin.com/profile/add?' + Object.entries(params)
          .map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&');
      }
    }
  }
}

const STATUS = { vazio: 200, valido: 200, invalido: 200, nao_encontrado: 404, limite: 429, indisponivel: 503 };
const CARDS = {
  vazio: '',
  invalido: '<div class="card"><p class="status bad">✗ Este documento não é mais válido.</p></div>',
  nao_encontrado: '<div class="card"><p class="status bad">Documento não encontrado.</p>Confira o ID e tente de novo.</div>',
  limite: '<div class="card"><p class="status bad">Muitas consultas.</p>Aguarde um minuto e tente de novo.</div>',
  indisponivel: '<div class="card"><p class="status bad">Serviço temporariamente indisponível.</p>Tente de novo em alguns minutos.</div>',
};
const card = resultado === 'valido' ? `<div class="card">
    <p class="status ok">✓ Documento válido</p>
    <dl>
      <dt>Documento</dt><dd>${esc(doc.tipo)}</dd>
      <dt>Nome</dt><dd>${esc(doc.nome)}</dd>
      <dt>Curso</dt><dd>${esc(doc.curso)}</dd>
      ${doc.carga_horaria ? `<dt>Carga horária</dt><dd>${esc(doc.carga_horaria)} horas</dd>` : ''}
      <dt>Emissão</dt><dd>${esc(doc.data_emissao)}</dd>
    </dl>
    ${linkedin ? `<a class="linkedin" href="${esc(linkedin)}" target="_blank" rel="noopener noreferrer">Adicionar ao LinkedIn</a>` : ''}
  </div>` : CARDS[resultado];

const html = `<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Validação de documentos</title>
<style>
  body { margin: 0; font-family: system-ui, sans-serif; background: #f2f5f5; color: #1f2a2b; }
  header { background: #0f3d3e; color: #fff; padding: 28px 16px; text-align: center; }
  header h1 { margin: 0; font-size: 1.25rem; letter-spacing: .04em; }
  header p { margin: 6px 0 0; opacity: .75; font-size: .9rem; }
  main { max-width: 520px; margin: 24px auto; padding: 0 16px; }
  form { display: flex; gap: 8px; }
  input { flex: 1; min-width: 0; padding: 10px 12px; font-size: 1rem; border: 1px solid #c3d0d0; border-radius: 8px; }
  button { padding: 10px 16px; font-size: 1rem; border: 0; border-radius: 8px; background: #0e7c7b; color: #fff; cursor: pointer; }
  .card { margin-top: 20px; background: #fff; border-radius: 12px; padding: 20px; box-shadow: 0 1px 3px rgba(0,0,0,.08); }
  .status { font-weight: 700; font-size: 1.1rem; margin: 0 0 12px; }
  .ok { color: #1d7a45; } .bad { color: #b3261e; }
  dl { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 8px 16px; }
  dt { color: #5f6f70; } dd { margin: 0; font-weight: 600; }
  a.linkedin { display: block; margin-top: 16px; padding: 10px 16px; border-radius: 8px; background: #0a66c2;
               color: #fff; text-align: center; text-decoration: none; font-weight: 600; }
</style>
</head>
<body>
<header>
  <h1>VALIDAÇÃO DE DOCUMENTOS</h1>
  ${EMISSOR ? `<p>${esc(EMISSOR)}</p>` : ''}
</header>
<main>
  <form method="get" action="">
    <input name="id" value="${esc(id)}" placeholder="ID de validação" aria-label="ID de validação" maxlength="64" required>
    <button type="submit">Validar</button>
  </form>
  ${card}
</main>
</body>
</html>`;

return [{ json: { html, status: STATUS[resultado] } }];
